// Type-level safeguarding test for requirement: markline-symboloffset-2d-array
// Verifies markLine `symbolOffset` accepts a 2D array (separate offset pairs
// for the two end symbols) while existing simpler forms stay valid.
// Run: npx tsc --noEmit --strict --target es2017 --moduleResolution node agent_tests/markline-symboloffset-2d-array.ts
import { MarkLineOption, MarkLine1DDataItemOption } from '../src/component/marker/MarkLineModel';

// New capability: 2D array, separate offset pairs for both end symbols
const twoD: MarkLineOption = {
    symbolOffset: [[10, 20], ['-50%', 0]]
};
const itemTwoD: MarkLine1DDataItemOption = {
    yAxis: 10,
    symbolOffset: [[0, 0], [5, '10%']]
};

// Existing simpler forms must remain valid
const scalar: MarkLineOption = { symbolOffset: 5 };
const str: MarkLineOption = { symbolOffset: '10%' };
const oneD: MarkLineOption = { symbolOffset: [10, 20] };

export { twoD, itemTwoD, scalar, str, oneD };
